BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-22102'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='BTR001' OR source_url ~ '[?&]id=22102(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='7c12b001-b8ac-49fb-9a37-553071322102' OR slug='sam-former-factory-setthakit-1-om-noi-btr001' OR (abs(latitude-13.68212)<0.0001 AND abs(longitude-100.288101)<0.0001 AND abs(land_area_sqm-25360)<1)) THEN RAISE NOTICE 'SAM BTR001 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('7c12b001-b8ac-49fb-9a37-553071322102', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'factory', 'business', 'sale', 'whole_property', 'โรงงานเดิมถนนเศรษฐกิจ 1 อ้อมน้อย 15 ไร่ 3 งาน 40 ตร.ว. · รื้อถอนส่วนใหญ่', 'รายละเอียดทรัพย์

ทรัพย์โรงงานเดิม เลขที่ 116 ถนนเศรษฐกิจ 1 (ทล.3091) ตำบลอ้อมน้อย อำเภอกระทุ่มแบน จังหวัดสมุทรสาคร ที่ดินโฉนดเลขที่ 48274 และ 53224 รวม 15 ไร่ 3 งาน 40 ตร.ว. หรือ 6,340 ตร.ว. (25,360 ตร.ม.) ราคาประกาศขาย SAM 173,853,000 บาท รหัส BTR001

แปลงรูปหลายเหลี่ยม ด้านตะวันตกกว้างประมาณ 212 เมตร โดยมีส่วนติดถนนประมาณ 158 เมตร ลึกสุดประมาณ 178 เมตร ถนนเศรษฐกิจ 1 ตาม SAM เป็นทางสาธารณประโยชน์ ผิวลาดยางกว้างประมาณ 18 เมตร เขตทางประมาณ 30 เมตร

สภาพและรายการสิ่งปลูกสร้าง

SAM จัดหมวดโรงงาน/โกดัง แต่ระบุว่าอาคารส่วนใหญ่ทรุดโทรมและถูกรื้อถอน สำรวจพบสิ่งปลูกสร้างเหลือเพียงรายการที่ 1 และ 14 โดยรายการที่ 1 ตามทะเบียนรับโอนเป็นสำนักงาน 3 ชั้นเลขที่ 116 แต่ในข้อความสำรวจเรียกว่าอาคารพักอาศัย 3 ชั้น ส่วนรายการที่ 14 เป็นอาคารหอพัก 4 ชั้น จึงควรยืนยันการใช้ประโยชน์และสภาพอาคารจริง ไม่ถือเป็นโรงงานพร้อมดำเนินกิจการ

ทะเบียนรับโอนมี 14 รายการ ได้แก่ สำนักงาน 3 ชั้น, โรงจอดรถชั้นเดียว 2 หลัง, โรงงานปั๊มเหล็กรางลูกฟูก, อาคารโพลียูรีเทน, หอพักหญิง 2 ชั้น, โรงงานตาข่ายหกเหลี่ยม, อาคารเก็บของ, ป้อมยาม, โรงงานตาข่ายสี่เหลี่ยม, สำนักงาน 2 ชั้น, โรงงานตาข่ายเทพื้น, โรงงานชุบลวดสังกะสี/รีดเหล็ก, โรงงานรีดใหญ่ และหอพักชาย 4 ชั้น เป็นรายการตามทะเบียนเดิม ไม่ใช่การรับรองว่าสิ่งปลูกสร้างทุกหลังยังอยู่ครบ

ภาพจาก SAM วันที่ 16 พฤษภาคม 2568 แสดงเศษวัสดุรื้อถอน ผนังและโครงหลังคาบางส่วน ควรตรวจโครงสร้างที่เหลือ รายการที่รวมในการโอน และความรับผิดชอบเรื่องรื้อถอนหรือขนย้ายเศษวัสดุก่อนเสนอซื้อ ต้นทางไม่ระบุพื้นที่ใช้สอยรวม จำนวนห้อง หรือใบอนุญาตโรงงานปัจจุบัน

ข้อควรทราบเรื่องภาระจำยอมและผังเมือง

โฉนด 48274 (เลขเดิม 12527) บางส่วนตกอยู่ในบังคับภาระจำยอมของโฉนด 30584 ตามข้อมูล SAM เป็นแนวด้านใต้กว้างประมาณ 6 เมตรตลอดแนว รวมประมาณ 2 งาน 67 ตร.ว. หรือ 267 ตร.ว. ซึ่งรวมในพื้นที่ทั้งหมด ต้องตรวจขอบเขตและเงื่อนไขภาระจำยอมก่อนวางแผนใช้ที่ดิน

แม้หัวข้อสรุป SAM แสดงสีม่วง รายละเอียดระบุผังเมืองรวมเมืองกระทุ่มแบน พ.ศ.2562 ครอบคลุมทั้งสีม่วงบริเวณ อ.2-3 (อุตสาหกรรมและคลังสินค้า) และสีเขียวอ่อนบริเวณ ล.2-9 (พื้นที่โล่งเพื่อนันทนาการและการรักษาคุณภาพสิ่งแวดล้อม) จึงไม่ควรถือว่าทั้งแปลงใช้ทำอุตสาหกรรมได้เหมือนกัน

สำหรับส่วนสีเขียวอ่อน SAM ระบุการใช้ประโยชน์เพื่อนันทนาการ ส่งเสริมรักษาคุณภาพสิ่งแวดล้อม บ้านเดี่ยว สถาบันราชการ สาธารณูปโภคและสาธารณูปการ อัตราส่วนพื้นที่อาคารรวมต่อที่ดินไม่เกิน 1.5:1 และที่ว่างปราศจากอาคารไม่น้อยกว่า 40% ข้อมูลนี้เป็นข้อกำหนดที่ SAM อ้างจากผังปี 2562 ผู้สนใจควรตรวจผังปัจจุบัน แนวแบ่งสีและข้อกำหนดกับหน่วยงานก่อนตัดสินใจ

ทำเลและการเดินทาง

อยู่ในย่านที่อยู่อาศัยและอุตสาหกรรม ใกล้สำนักงานตรวจคนเข้าเมืองกระทุ่มแบน สนามกีฬาเทศบาลนครอ้อมน้อยคลังทองและสำนักงานประกันสังคม จากหนองแขมมุ่งหน้าสามพรานบนถนนเพชรเกษม ผ่านโรงพยาบาลมหาชัย 2 และไทวัสดุ เลี้ยวซ้ายเข้าถนนเศรษฐกิจ 1 ผ่านตลาดเทศบาลอ้อมน้อยถึงประมาณ กม.3 ทรัพย์อยู่ซ้ายมือ

ภาพและข้อมูลต้นทาง

ภาพจริงและผังจาก SAM รวม 17 ภาพ พิกัด 13.682120, 100.288101 ดึงจากลิงก์นำทางและตรงกับลิงก์แผนที่ SAM เป็นตำแหน่งอ้างอิง ไม่ใช่แนวเขตรังวัด ราคาและสถานะซื้อตรงตรวจวันที่ 15 กันยายน 2569 ติดต่อ SAM 02-686-1888, sales@sam.or.th หรือ LINE @samline แจ้งรหัส BTR001 เพื่อยืนยันสถานะ ราคา สภาพและเงื่อนไขล่าสุด', 173853000, false, 25360, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, '116 ถนนเศรษฐกิจ 1', 'บริเวณ ทล.3091 กม.3', 'ถนนเศรษฐกิจ 1 (ทล.3091)', 13.68212, 100.288101, 'สมุทรสาคร', 'กระทุ่มแบน', 'อ้อมน้อย', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-former-factory-setthakit-1-om-noi-btr001') RETURNING id INTO property_listing_id;
