INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=22102&keyref=', 'BTR001', now(), 'Checked2026-09-15. THB173853000,25360sqm. Factory mostly demolished;historic14 entries,survey remaining1/14 with office/residential naming discrepancy.267sq.wah southern easement included. Mixed purple/light-green2019 source zoning and restrictions require current verification.17 authentic images dated2025-05-16;navigation/map agree. No all-status source/page/deed/nearby matches;additional map-filename3A0721 search empty.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Former Factory, Setthakit1 Om Noi — Mostly Demolished, THB173.853M', 'Former factory property numbered116 on Setthakit1 Road (Highway3091), Om Noi, Krathum Baen, Samut Sakhon. Chanote titles48274 and53224 total15 rai3 ngan40 sq.wah, or6,340 sq.wah (25,360 sq.m.). SAM announced price THB173,853,000, asset BTR001. Polygonal site,212m western side with158m road frontage and178m maximum depth. Public road per SAM,18m paved carriageway and30m right of way.

Condition: SAM categorises it factory/warehouse but reports most structures dilapidated and demolished. Survey says only registered items1 and14 remain. Item1 is a three-storey office116 in the acquisition register but called a three-storey residential building in the survey; item14 is a four-storey dormitory. Verify actual use and condition; not advertised as an operational factory.

The historic register lists14 entries: three-storey office,two single-storey carports,corrugated-steel forming factory,polyurethane building,two-storey female dormitory,hexagonal-mesh factory,store,guardhouse,square-mesh factory,two-storey office,floor-mesh factory,wire galvanising/steel rolling factory,large rolling factory and four-storey male dormitory. This is a historic inventory,not confirmation all survive. Photos dated16 May2025 show demolition debris,walls and partial roof structures. Verify structural condition,transfer inventory and demolition/debris-removal responsibility. Total usable area,room counts and current factory licence are not published.

Material easement: part of deed48274 (formerly12527) is burdened in favour of deed30584,according to SAM,along the southern side approximately6m wide,area267sq.wah included in total. Check exact scope and terms.

Mixed zoning: although the summary says purple,SAM''s detailed text cites the2019 Krathum Baen comprehensive plan with purple industrial/warehouse area อ.2-3 and light-green recreation/environmental open-space area ล.2-9. Do not treat the whole site as unrestricted industrial land. For light-green land,SAM reports recreation,environmental protection,detached housing,government institutions and public utilities/facilities as uses,maximum FAR1.5:1 and minimum40% building-free land. These are source-attributed2019 rules; verify current zoning boundaries and requirements with the authority before purchase.

Residential/industrial surroundings near Krathum Baen Immigration,Om Noi Khlang Thong municipal sports ground and Social Security Office. From Nong Khaem toward Sam Phran on Phetkasem,pass Mahachai2 Hospital and Thai Watsadu,turn left into Setthakit1 past Om Noi municipal market to aroundkm3,property left.

Seventeen authentic source images/plans. Navigation/map agree13.682120,100.288101,reference pin not surveyed boundary. Price/direct-sale status checked15 September2026. Contact SAM02-686-1888,sales@sam.or.th or LINE@samline quoting BTR001.', '116 Setthakit1 Road', 'Highway3091 aroundkm3', 'Setthakit1 Road (Highway3091)', 'Om Noi', 'Krathum Baen', 'Samut Sakhon', 'Former Factory, Setthakit1 Om Noi — Mostly Demolished, THB173.853M', 'Former factory25360sqm,THB173853000,mostly demolished;267sq.wah easement and mixed purple/light-green zoning disclosed.', 'published', 'ai_assisted', now(), 'former factory, setthakit1 om noi — mostly demolished, thb173.853m former factory property numbered116 on setthakit1 road (highway3091), om noi, krathum baen, samut sakhon. chanote titles48274 and53224 total15 rai3 ngan40 sq.wah, or6,340 sq.wah (25,360 sq.m.). sam announced price thb173,853,000, asset btr001. polygonal site,212m western side with158m road frontage and178m maximum depth. public road per sam,18m paved carriageway and30m right of way.

